const vector = $json.data[0].embedding;
const literal = '[' + vector.join(',') + ']';
const sql = "SELECT p.numero_documento, p.tipo_documento, p.primer_nombre, p.segundo_nombre, p.apellidos, " +
  "p.fecha_nacimiento, EXTRACT(YEAR FROM age(CURRENT_DATE, p.fecha_nacimiento))::int AS edad, " +
  "p.genero, p.correo, p.celular, p.created_at, " +
  "1 - (pe.embedding <=> '" + literal + "'::vector) AS similitud " +
  "FROM persona_embeddings pe " +
  "JOIN personas p ON p.numero_documento = pe.numero_documento " +
  "ORDER BY pe.embedding <=> '" + literal + "'::vector LIMIT 5";
return [{ json: { sql } }];

const original = $('Chat Trigger').first().json.chatInput || '';
const pregunta = original.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const rango = pregunta.match(/(?:mas de|mayor(?:es)? de|superior a|al menos|menos de|m[ae]nor(?:es)? de)\s+(\d{1,3})/);
const exacta = pregunta.match(/(?:tienen|de|con)\s+(\d{1,3})\s+a[ñn]os/);
const mayorEdad = /\b(?:mayores?(?:\s+de\s+edad)?|adultos?)\b/.test(pregunta) && !rango && !exacta;
const menorEdad = /\bm[ae]nores?(?:\s+de\s+edad)?\b/.test(pregunta) && !rango && !exacta;
let ageMode = '';
let ageLimit = 0;
if (rango) {
  ageMode = /^(?:menos de|m[ae]nor)/.test(rango[0]) ? 'lt' : /^al menos/.test(rango[0]) ? 'gte' : 'gt';
  ageLimit = Number(rango[1]);
} else if (exacta) {
  ageMode = 'eq';
  ageLimit = Number(exacta[1]);
} else if (mayorEdad) {
  ageMode = 'gte';
  ageLimit = 18;
} else if (menorEdad) {
  ageMode = 'lt';
  ageLimit = 18;
}
const camposNoDisponibles = [];
if (/\b(direccion|ciudad|municipio|barrio|donde|vive|viven)\b/.test(pregunta)) camposNoDisponibles.push('dirección y ciudad');
if (/\b(cargo|area|puesto|profesion|trabaja|trabajan)\b/.test(pregunta)) camposNoDisponibles.push('cargo y área de trabajo');
const documento = pregunta.match(/(?:documento|cedula|identificacion)\D{0,15}(\d{5,10})/) || (!rango && pregunta.match(/\b\d{6,10}\b/));
const comunes = new Set('a al anos apellidos area barrio cargo celular ciudad como con cual cuales cuanto cuantos cuanta cuantas de del dime dice documento donde edad el electronico email empleada empleado empleados en es esta estan existe fecha genero ha hay identificacion informacion la las los mas mayor mayores me menor menores municipio mujer mujeres nacimiento nacio necesito no nombre numero o por persona personas podria podrias profesion puesto que quien quienes registrado registrada registrados registradas registro se sexo son telefono tienen trabaja trabajan un una y vive viven correo direccion tipo'.split(' '));
const objetivo = camposNoDisponibles.length ? '' : documento ? documento[1] : pregunta.replace(/[^a-z0-9]+/g, ' ').trim().split(/\s+/).filter((word) => word && !comunes.has(word) && !/^\d+$/.test(word)).join(' ');
return [{ json: { pregunta: original, objetivo, ageMode, ageLimit, camposNoDisponibles } }];

const consulta = $json;
const pregunta = consulta.pregunta.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const conteo = /\b(?:cuantos|cuantas)\b/.test(pregunta) && /\b(?:personas|empleados|hombres|mujeres|masculino|femenino|cedula|cedulas|tarjeta|tarjetas|mayores|menores)\b/.test(pregunta);
const ubicacion = /\b(direccion|direcciones|ciudad|ciudades|municipio|municipios|barrio|barrios|donde|vive|viven|reside|residen)\b/.test(pregunta);
if (ubicacion && !consulta.camposNoDisponibles.includes('dirección y ciudad')) consulta.camposNoDisponibles.push('dirección y ciudad');
const trabajo = /\b(cargo|cargos|area|areas|puesto|puestos|profesion|profesiones|trabaja|trabajan|trabajo)\b/.test(pregunta);
if (trabajo && !consulta.camposNoDisponibles.includes('cargo y área de trabajo')) consulta.camposNoDisponibles.push('cargo y área de trabajo');
const documento = pregunta.match(/\b(\d{5,10})\b/);
const stop = new Set('a al anos apellidos area barrio cargo celular ciudad como con cual cuales cuanto cuantos cuanta cuantas de del dime dice documento donde edad el electronico email empleada empleado empleados en es esta estan existe fue fecha genero ha hay hombre hombres identificacion informacion la las los mas mayor mayores me menor menores municipio mujer mujeres nacimiento nacio necesito no nombre numero o por favor persona personas podria podrias profesion puesto que quien quienes registrado registrada registrados registradas registro registrar registrarse registrando se sexo son telefono tiene tienen trabaja trabajan trabajo un una y vive viven correo direccion tipo muestra mostrar indica indicar consulta consultar datos verifica verificar encuentra promedio total masculino femenina femenino reciente recientes ultimo ultima ultimos ultimas joven jovenes viejo viejos'.split(' '));
const palabras = pregunta.replace(/[^a-z0-9]+/g, ' ').trim().split(/\s+/).filter((word) => word && !stop.has(word) && !/^\d+$/.test(word));
if (consulta.camposNoDisponibles.length) consulta.objetivo = '';
else if (documento && !/\b(?:edad|ano|anos)\b/.test(pregunta)) consulta.objetivo = documento[1];
else if (palabras.length > 0) consulta.objetivo = palabras.join(' ');
else if (conteo) consulta.objetivo = '';
else consulta.objetivo = '';
return [{ json: consulta }];

const consulta = $('Ajustar consulta').first().json;
const similares = $('Buscar similares').all().map((item) => item.json);
const agregados = $('Agregados').first().json;
const contexto = JSON.stringify({ similares, agregados, filtro_edad: { modo: consulta.ageMode, edad: consulta.ageLimit }, campos_no_disponibles: consulta.camposNoDisponibles }, null, 2);
return [{ json: { pregunta: consulta.pregunta, contexto } }];

const respuestaModelo = String($json.choices[0].message.content || '').trim();
const pregunta = $('Armar contexto').first().json.pregunta.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const agregados = $('Agregados').first().json;
const porGenero = typeof agregados.por_genero === 'string' ? JSON.parse(agregados.por_genero) : (agregados.por_genero || {});
const porTipoDoc = typeof agregados.por_tipo_documento === 'string' ? JSON.parse(agregados.por_tipo_documento) : (agregados.por_tipo_documento || {});
const mayoria = typeof agregados.conteo_mayoria_edad === 'string' ? JSON.parse(agregados.conteo_mayoria_edad) : (agregados.conteo_mayoria_edad || {});
const pideConteo = /\b(cuant[oa]s?|cantidad|total|conteo|numero)\b/.test(pregunta);

if (pideConteo) {
  if (/\b(cedula(?:s)?)\b/.test(pregunta)) {
    const cant = Number(porTipoDoc['Cédula'] || porTipoDoc['Cedula'] || 0);
    return [{ json: { texto: `Hay ${cant} ${cant === 1 ? 'persona' : 'personas'} con tipo de documento Cédula.` } }];
  }
  if (/\b(tarjeta(?:s)?(?:\s+de\s+identidad)?)\b/.test(pregunta)) {
    const cant = Number(porTipoDoc['Tarjeta de identidad'] || 0);
    return [{ json: { texto: `Hay ${cant} ${cant === 1 ? 'persona' : 'personas'} con tipo de documento Tarjeta de identidad.` } }];
  }
  if (/\b(mayores?(?:\s+de\s+edad)?|adultos?)\b/.test(pregunta) && !/\b(menor|manor)\b/.test(pregunta)) {
    const cant = Number(mayoria.mayores_de_edad || 0);
    return [{ json: { texto: `Hay ${cant} ${cant === 1 ? 'persona mayor' : 'personas mayores'} de edad registradas.` } }];
  }
  if (/\bm[ae]nores?(?:\s+de\s+edad)?\b/.test(pregunta)) {
    const cant = Number(mayoria.menores_de_edad || 0);
    return [{ json: { texto: `Hay ${cant} ${cant === 1 ? 'persona menor' : 'personas menores'} de edad registradas.` } }];
  }
  if (/\b(mujer(?:es)?|femenin[oa]s?)\b/.test(pregunta)) {
    const cant = Number(porGenero['Femenino'] || porGenero['femenino'] || 0);
    return [{ json: { texto: `Hay ${cant} ${cant === 1 ? 'mujer registrada' : 'mujeres registradas'}.` } }];
  }
  if (/\b(hombre(?:s)?|masculin[oa]s?)\b/.test(pregunta)) {
    const cant = Number(porGenero['Masculino'] || porGenero['masculino'] || 0);
    return [{ json: { texto: `Hay ${cant} ${cant === 1 ? 'hombre registrado' : 'hombres registrados'}.` } }];
  }
}

let textoLimpio = respuestaModelo.replace(/^(?:para responder a tu pregunta,?\s*(?:analic[eé] el contexto[^.]*\.?)?|seg[uú]n el contexto (?:proporcionado|analizado),?|de acuerdo con el contexto,?|seg[uú]n los agregados,?)\s*/i, '').trim();
const pideCorreo = /\b(correo|email|electronico)\b/.test(pregunta);
if (!pideCorreo) {
  textoLimpio = textoLimpio.replace(/(?:(?:\.\s*)|\s+)?(?:su\s+)?correo(?:\s+electr[oó]nico)?\s+(?:es\s+)?[^\s@]+@[^\s@]+\.?/gi, '.').replace(/\s*\.\s*\./g, '.').replace(/\s+/g, ' ').trim();
}
const pideTelefono = /\b(celular|telefono|contacto|whatsapp)\b/.test(pregunta);
if (!pideTelefono) {
  textoLimpio = textoLimpio.replace(/(?:(?:\.\s*)|\s+)?(?:su\s+)?(?:tel[eé]fono|celular)\s+(?:es\s+)?\+?[\d\s-]{7,}\.?/gi, '.').replace(/\s*\.\s*\./g, '.').replace(/\s+/g, ' ').trim();
}
return [{ json: { texto: textoLimpio } }];
